style.css:
@-moz-document domain("deltamath.com") {
/* Main Background */
    body, .container, .main-content {
        background-color: #ffe6f2 !important; /* Light Pink */
    }

    /* Header and Navigation */
    .navbar, .header, .top-bar {
        background-color: #ffb6c1 !important;
        color: #7a3b56 !important;
    }

    /* Sidebar and Menus */
    .sidebar, .menu, .dropdown-menu, .panel {
        background-color: #ffccd5 !important;
        color: #7a3b56 !important;
    }

    /* Cards and Content Boxes */
    .card, .panel-body, .content-box {
        background-color: #ffc1cc !important;
        color: #7a3b56 !important;
    }

    /* Buttons */
    .btn, .btn-primary, .btn-secondary, .button {
        background-color: #ff99aa !important;
        color: #fff !important;
        border-color: #ff7f9c !important;
    }

    /* Hover Effects */
    .btn:hover, .button:hover, .dropdown-item:hover {
        background-color: #ff8099 !important;
    }

    /* Input Fields */
    input, textarea, select {
        background-color: #ffd9e3 !important;
        color: #000 !important;
        border-color: #ffb6c1 !important;
    }

    /* Text Colors */
    * {
        color: #7a3b56 !important; /* Dark pink text */
    }

    /* Disable Text Selection and Background Highlighting */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
